-- GENERATED by `wfj generate` from data/gossip/gossip-f4.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["f40a40e19d8e51f6"] = { "Questo {name} è senza dubbio un servitore dell'incubo di Naralex!", "." },
  ["f40b877b09dad351"] = { "Devi essere in rapporti amichevoli con i Reietti di ⟦Undercity=Sepulcra⟧ prima che io ti insegni a cavalcare, {class}.", "." },
  ["f415ba3f42680c9e"] = { "Ehi, amico, che posso fare per te?", "." },
  ["f419074ea5490c55"] = { "È semplice, davvero. Priva il lich, ⟦Ras Frostwhisper=Ras Soffiogelo⟧, dei suoi poteri. Riportalo alla sua forma mortale e poi uccidilo, una volta per tutte.", "." },
  ["f41ae68c4a3e3d5a"] = { "La ⟦Irondeep Mine=Miniera di Ferrofondo⟧ è in mano all'⟦Horde=Orda⟧.", "." },
  ["f420a2c502f9252e"] = { "⟦Thorium Brotherhood=Fratellanza del Torio⟧ o no, se uno di quei ⟦Dark Iron=Ferroscuro⟧ mi si avvicina, assaggerà il mio piccone sulla tempia! Allora, dove posso mandarti, <ragazzo/ragazza>?", "." },
  ["f425ea91baae73aa"] = { "Ci stiamo preparando alla guerra, {class}. Ne abbiamo abbastanza dei Silitidi e dei loro padroni ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. Per prepararci stiamo raccogliendo materiali di ogni tipo. Io mi occupo di raccogliere la ⟦Arthas' Tears=Lacrima di Arthas⟧. Non so bene a cosa ci serva, però. Se lo chiedi a me, non voglio averci niente a che fare con quel pazzo, anche se si tratta solo di un fiore che porta il suo nome.\n\nComunque sono figlia di mio padre, e un soldato, quindi faccio quello che mi dicono. Al momento ne abbiamo $2057w e dobbiamo raccoglierne in tutto $2058w.", "." },
  ["f4262ee41c73def7"] = { "Non ho molto tempo per le chiacchiere, {name}. Devo ricostruire questo ponte prima che arrivino le piogge. Ho finito ogni progetto nei tempi e senza sforare il budget, e non ho intenzione di cominciare a sgarrare adesso.", "." },
  ["f42685a7fb33e54b"] = { "E RESTA nella tomba!", "." },
  ["f42c5d49be43294f"] = { "Certo. Ti aspetta nella biblioteca.", "." },
  ["f42e2ab409d6884f"] = { "Va' alla ⟦Great Forge=Grande Forgia⟧, proprio al centro di ⟦Ironforge=Forgiardente⟧. Lavora lì, insieme agli altri Maestri della nostra gente.", "." },
  ["f4359724886020d5"] = { "È ora che tu ti rechi a Darnassus a parlare con Me'lynn. D'ora in poi sarà lei a guidarti.", "." },
  ["f4365d2614299fad"] = { "Soldato, chiama subito il capitano Neraforgia!", "." },
  ["f438343f439bebe6"] = { "Ho raggiunto l'ultimo punto di passaggio. Evviva!", "." },
  ["f43a752b1ae32b14"] = { "Non credo ci siano pesci in questi canali.", "." },
  ["f44d3f68bdfe603d"] = { "Muori nel nome di Ragnaros!", "." },
  ["f45201221f7a1663"] = { "Buona giornata, <ragazzo/ragazza>. Posso esserti utile?", "." },
  ["f461001ec2d60924"] = { "Mi fai perdere tempo, va' a parlare con il mio allievo Basil.", "." },
  ["f46824e69663cc78"] = { "Il Capoguerra porta un cambiamento che darà la vittoria all'⟦Horde=Orda⟧! Cerca Swart dentro la caserma, sul lato est della città.", "." },
  ["f4684f836fbb8f15"] = { "Io preferisco il cibo crudo, ma se a te piace cotto, Denni'ka può insegnarti ad accendere un fuoco. La trovi a Survival of the Fittest, una capanna sulla riva del lago accanto alla Spirit Lodge. Cercala più in alto, a ovest della ⟦Valley of Strength=Valle della Forza⟧.", "." },
  ["f469305efaad3546"] = { "Sciocchi! Queste uova sono più preziose di quanto immaginiate!", "." },
  ["f470fc0654e9af2d"] = { "Questo lascerà il segno!", "." },
  ["f4737aefecc45612"] = { "La guerra è alle porte, {name}. È ora che ogni membro dell'⟦Horde=Orda⟧ risponda alla chiamata e si unisca alla lotta contro la codarda ⟦Alliance=Alleanza⟧.", "." },
  ["f47a067c99f103e2"] = { "Ben fatto! Hai quella scintilla negli occhi... la conosco bene, è la stessa che avevo io quand'ero solo un cucciolo! Ora vediamo se posso insegnarti qualcosa.", "." },
  ["f47a1635ea331ae3"] = { "Non puoi nasconderti da me, <ladro/ladra>. Sento l'odore della tua paura.", "." },
  ["f47ff9121524700d"] = { "Grazie per aver tolto di mezzo quei senatori sciocchi. Ora preparati ad affrontare la tua fine per mano del più potente servitore di Ragnaros.", "." },
  ["f480178f3e81387b"] = { "Speriamo che funzioni!", "." },
  ["f481259da3201f36"] = { "%s esplode in pezzi di melma acida!", "." },
  ["f481e957bf03bf6f"] = { "Ti giuro amore eterno. La morte non può cancellarlo, così come so per certo che ricordi ancora il tuo amore per me.", "." },
  ["f4866e5b593310f6"] = { "Io so parlare la lingua dei gatti, e ⟦Effsee=Mentegatto⟧ ha detto grazie.", "." },
  ["f4904de2cd305932"] = { "Un mio ex allievo di nome Krixix passò una vita intera a cercare di mettersi in contatto con gli dèi incatenati del mondo sotterraneo. Inseguiva ciò che sarebbe sgorgato dalla terra devastata... Ciò che si sarebbe formato solo come risultato dello scontro titanico tra gli elementi.\n\nL'Elementio, come lo avrebbero conosciuto i mortali.\n\nUn giorno, quasi dieci anni fa, la ricerca di Krixix portò all'apertura di una fenditura proprio in questa gola.", "." },
  ["f494ad945e451a38"] = { "Ciao, Quinn. Come te la passi?", "." },
  ["f496ec52e809112c"] = { "Ascolta, <giovanotto/signorina>, sappi che qualunque cosa ci abbia attaccati non era una sacerdotessa di un bel niente! Gli occhi le brillavano di qualcosa di malvagio e aveva letteralmente la bava alla bocca! È entrata, ha lanciato una specie di urlo folle che ci ha fatti scappare tutti in direzioni diverse, e poi ha cominciato a straziarci la mente uno per uno. Sentivo parole oscure nella testa e vedevo gli altri perdere i sensi di tanto in tanto, qua e là. Era follia! Saremmo stati spacciati, se non fosse stato per quella dannata scimmia.", "." },
  ["f49b2b0146cffbad"] = { "Il buon vecchio Thamner mi ha bendato proprio l'altro giorno, quando ho avuto un brutto incontro con un trogg. Sto una meraviglia, te lo dico io! Di sicuro Thamner sarebbe felice di insegnarti a fare una buona benda.", "." },
  ["f49e00c28e9b0e51"] = { "%s si trova al cospetto della ⟦Might of Kalimdor=Forza di Kalimdor⟧.", "." },
  ["f4aea43239c595e5"] = { "Athrikus venne da noi. Ci disse che poteva salvarci dal male. Lanciò su di noi un incantesimo per proteggerci dal male.", "." },
  ["f4b60bc2251fc324"] = { "Quei giorni sono finiti, Eris.", "." },
  ["f4c773fa3bf82d19"] = { "Posso insegnarti sia la finezza di una lama corta, sia la potenza devastante e spaccaossa di un colosso a due mani. Oppure possiamo esagerare e te le insegno entrambe: potrebbe tornarti utile quando la situazione cambia.", "." },
  ["f4e0a50c9161178b"] = { "Anche tu sei qui per dimostrare il tuo valore?", "." },
  ["f4eb71c5b6bb2692"] = { "So pochissimo degli ⟦Highborne=Alti Nobili⟧ e niente degli Shen'dralar.", "." },
  ["f4ecbaead1ca8662"] = { "Dicono che qui viva Cairne in persona. Quando avrò finito di realizzare un dono degno di lui, andrò a cercarlo. Forse avrà parole di saggezza per me.", "." },
  ["f4f30325de1c73b7"] = { "Stoltamente hai cercato la tua stessa rovina. Sfacciatamente hai ignorato poteri che vanno oltre la tua comprensione. Hai lottato duramente per invadere il regno del mietitore. Ora c'è una sola via d'uscita: percorrere il sentiero solitario dei dannati.", "." },
  ["f4fa9a88b9406c19"] = { "Hai fatto bene a venire. La mia saggezza sarà tua.", "." },
})
